background-color: null;
font-style: inherit;">:</span>N</span>
<span id="cb14-10">        y[i] <span class="op" style="color: #5E5E5E;
background-color: null;
font-style: inherit;">~</span> <span class="fu" style="color: #4758AB;
background-color: null;
font-style: inherit;">Categorical</span>(probabilities[<span class="op" style="color: #5E5E5E;
background-color: null;
